import{_ as i,o as a,c as o,a2 as t}from"./chunks/framework.F7eQ-ohH.js";const c=JSON.parse('{"title":"政治常识（核心模块）","description":"","frontmatter":{},"headers":[],"relativePath":"行测/基本常识/1.常识概述.md","filePath":"行测/基本常识/1.常识概述.md","lastUpdated":1788883925000}'),u={name:"行测/基本常识/1.常识概述.md"};function r(e,l,s,n,h,d){return a(),o("div",null,[...l[0]||(l[0]=[t('<h1 id="政治常识-核心模块" tabindex="-1">政治常识（核心模块） <a class="header-anchor" href="#政治常识-核心模块" aria-label="Permalink to &quot;政治常识（核心模块）&quot;">​</a></h1><ol><li>马克思主义基本原理</li></ol><ul><li>哲学：唯物论、辩证法、认识论、历史唯物主义（高频考点：矛盾分析法、实践与认识的关系）</li><li>政治经济学：商品与货币、剩余价值、资本主义基本矛盾</li></ul><ol start="2"><li>中国特色社会主义理论体系</li></ol><ul><li>邓小平理论、“三个代表” 重要思想、科学发展观</li><li>习近平新时代中国特色社会主义思想（核心内容、重大论断、实践要求）</li></ul><ol start="3"><li>党和国家重大方针政策</li></ol><ul><li>最新党代会报告（核心要点、战略部署）</li><li>中央经济工作会议、中央一号文件等重要会议精神</li><li>治国理政新理念、新思想、新战略</li></ul><ol start="4"><li>党史、新中国史、改革开放史、社会主义发展史</li></ol><ul><li>重要历史事件、时间节点、历史意义</li><li>党的重要会议（一大到二十大关键内容）、伟大精神谱系</li></ul><h1 id="法律常识-高频模块" tabindex="-1">法律常识（高频模块） <a class="header-anchor" href="#法律常识-高频模块" aria-label="Permalink to &quot;法律常识（高频模块）&quot;">​</a></h1><ol><li>宪法</li></ol><ul><li>国家机构、公民的基本权利与义务、宪法修正案</li><li>国旗、国歌、国徽、首都等基本规定</li></ul><ol start="2"><li>行政法与行政诉讼法</li></ol><ul><li>行政主体、行政行为（行政许可、行政处罚、行政强制）</li><li>行政复议、行政诉讼的管辖与程序</li></ul><ol start="3"><li>民法与民事诉讼法</li></ol><ul><li>民事主体（自然人、法人、非法人组织）、民事权利（物权、债权、人格权）</li><li>合同编、侵权责任编核心条款（如违约责任、过错责任）</li></ul><ol start="4"><li>刑法与刑事诉讼法</li></ol><ul><li>犯罪构成、正当防卫与紧急避险、刑罚种类</li><li>常见罪名（盗窃、诈骗、交通肇事等高频考点）</li></ul><ol start="5"><li>其他常用法律</li></ol><ul><li>民法典最新修订内容、食品安全法、环境保护法、劳动法（劳动合同、工伤认定）</li></ul><h1 id="经济常识-基础模块" tabindex="-1">经济常识（基础模块） <a class="header-anchor" href="#经济常识-基础模块" aria-label="Permalink to &quot;经济常识（基础模块）&quot;">​</a></h1><ol><li>宏观经济学</li></ol><ul><li>国民经济指标（GDP、CPI、PPI、失业率）</li><li>财政政策与货币政策（工具、作用、调控目标）</li><li>通货膨胀与通货紧缩</li></ul><ol start="2"><li>微观经济学</li></ol><ul><li>供求理论、价格机制</li><li>市场类型（完全竞争、垄断竞争、寡头垄断、完全垄断）</li></ul><ol start="3"><li>国际经济与贸易</li></ol><ul><li>汇率、外汇储备</li><li>国际贸易组织（WTO）、区域经济一体化</li></ul><ol start="4"><li>中国经济热点</li></ol><ul><li>供给侧结构性改革、高质量发展</li><li>乡村振兴、共同富裕、数字经济等战略</li></ul><h1 id="人文常识-记忆型模块" tabindex="-1">人文常识（记忆型模块） <a class="header-anchor" href="#人文常识-记忆型模块" aria-label="Permalink to &quot;人文常识（记忆型模块）&quot;">​</a></h1><ol><li>中国古代史</li></ol><ul><li>朝代更替、重要政治制度（分封制、郡县制、科举制）</li><li>著名帝王、将相、文化名人及其贡献</li><li>重大历史事件（百家争鸣、安史之乱、辛亥革命等）</li></ul><ol start="2"><li>中国近现代史</li></ol><ul><li>鸦片战争后的重要战争与条约</li><li>近代化探索（洋务运动、戊戌变法、辛亥革命）</li><li>新民主主义革命时期关键节点</li></ul><ol start="3"><li>文化常识</li></ol><ul><li>传统节日、习俗与礼仪</li><li>文学典籍（四书五经、四大名著、唐宋八大家作品）</li><li>书法、绘画、戏曲、中医等传统文化瑰宝</li></ul><ol start="4"><li>世界人文</li></ol><ul><li>世界古代文明（古埃及、古巴比伦、古希腊、古罗马）</li><li>世界近现代重要事件、文艺复兴、工业革命</li><li>世界文学、艺术、科技名人及成就</li></ul><h1 id="科技常识-实用型模块" tabindex="-1">科技常识（实用型模块） <a class="header-anchor" href="#科技常识-实用型模块" aria-label="Permalink to &quot;科技常识（实用型模块）&quot;">​</a></h1><ol><li>自然科学基础</li></ol><ul><li>物理（力学、光学、电学核心原理）</li><li>化学（元素周期表基础、常见化学反应、化学物质用途）</li><li>生物（细胞结构、遗传规律、生态系统、人体生理）</li></ul><ol start="2"><li>高新技术</li></ol><ul><li>信息技术（5G、人工智能、大数据、云计算）</li><li>航空航天（中国航天工程、空间站、探测器）</li><li>新能源、新材料、生物技术（基因编辑、疫苗研发）</li></ul><ol start="3"><li>生活中的科技</li></ol><ul><li>常见科技常识（家电原理、交通安全、健康常识）</li><li>灾害防治（地震、火灾、洪水的应急处理）</li></ul><ol start="4"><li>中国科技成就</li></ol><ul><li>重大科技计划（863 计划、973 计划）</li><li>近五年重大科技突破（量子通信、高铁技术、核聚变等）</li></ul><h1 id="地理常识-综合型模块" tabindex="-1">地理常识（综合型模块） <a class="header-anchor" href="#地理常识-综合型模块" aria-label="Permalink to &quot;地理常识（综合型模块）&quot;">​</a></h1><ol><li>自然地理</li></ol><ul><li>地球运动（自转、公转及其地理意义）</li><li>气候类型、地形地貌、河流湖泊</li><li>自然资源（矿产、水资源、土地资源分布）</li></ul><ol start="2"><li>人文地理</li></ol><ul><li>人口、城市、交通布局</li><li>农业与工业区位因素</li></ul><ol start="3"><li>中国地理</li></ol><ul><li>行政区划（省、自治区、直辖市、特别行政区）</li><li>地形区（三大阶梯、四大高原、三大平原）</li><li>河流（长江、黄河、珠江）、湖泊及重要地理界线</li></ul><ol start="4"><li>世界地理</li></ol><ul><li>七大洲、四大洋分布</li><li>重要国家、首都、地形地貌（如亚马逊雨林、喜马拉雅山脉）</li><li>世界气候带、洋流分布 七、国情社情与管理常识（补充模块）</li></ul><ol><li>国情社情</li></ol><ul><li>中国的基本国情（人口、民族、自然资源）</li><li>行政区划、国旗国歌国徽、主要城市</li><li>最新人口普查、经济普查数据</li></ul><ol start="2"><li>管理常识</li></ol><ul><li>行政管理基础（政府职能、行政组织、公文写作规范）</li><li>公共管理、应急管理基本原则</li></ul><ol start="3"><li>公文常识</li></ol><ul><li>公文种类（通知、报告、请示、函等）</li><li>公文格式、行文规则</li></ul>',62)])])}const m=i(u,[["render",r]]);export{c as __pageData,m as default};
